return ['domain'=>'tranzly','plural-forms'=>'nplurals=6; plural=((((n % 100) >= 3 && (n % 100) <= 10)) ? 3 : (((n % 100) >= 11 && (n % 100) <= 99)) ? 4 : ((n == 1)) ? 1 : ((n == 2)) ? 2 : ((n == 0)) ? 0 : 5);','language'=>'ar','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T14:03:23+00:00','po-revision-date'=>'2026-09-26T14:03:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'WordPress متعدد اللغات، منشور واحد لكل لغة: ترجمات مرتبطة للمنشورات، والصفحات، والفئات، والنصوص الإعلامية، والأدوات، وعنوان الموقع، مع استيراد ترجماتك القديمة من Tranzly.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'مزودو الذكاء الاصطناعي','The makers of ChatGPT. A good all-rounder.'=>'صانعو ChatGPT. خيار شامل جيد.','The makers of Claude. Strong at writing and careful reasoning.'=>'مبدعو Claude. أداء قوي في الكتابة وتفكير دقيق.','Google\'s Gemini models. Fast and inexpensive.'=>'نماذج Gemini من Google. سريعة ومنخفضة التكلفة.','A European AI company with fast, inexpensive models.'=>'شركة ذكاء اصطناعي أوروبية تقدم نماذج سريعة ومنخفضة التكلفة.','Low-cost models that are good at writing and code.'=>'نماذج منخفضة التكلفة جيدة في الكتابة والبرمجة.','One key for models from many different providers.'=>'مفتاح واحد لنماذج من العديد من المزودين المختلفين.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'أي خدمة تعمل مثل واجهة برمجة تطبيقات OpenAI، بما في ذلك نموذج يعمل على جهازك أو خادمك الخاص.','General (used when nothing more specific is set)'=>'عام (يتم استخدامه عندما لا يتم تعيين أي شيء أكثر تحديداً)','Writing and rewriting'=>'الكتابة وإعادة الكتابة','Translation'=>'ترجمة','Code and CSS'=>'شفرة وملفات CSS','Sorry, you are not allowed to access this page.'=>'عذراً، لا يُسمح لك بالوصول إلى هذه الصفحة.','These settings are shared by every plugin that uses them: %s.'=>'تتم مشاركة هذه الإعدادات بواسطة كل ملحق يستخدمها: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'يتم تشفير مفاتيحك في قاعدة بيانات هذا الموقع ولا يتم إرسالها إلا إلى المزود الذي اخترته، ولا تُرسل إلينا أبداً.','Step 1 of 2: choose an AI provider'=>'الخطوة 1 من 2: اختر موفر ذكاء اصطناعي','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'أنت توفر مفتاحك الخاص، لذا تدفع للمزود مباشرة مقابل ما تستخدمه. لست متأكداً؟ أي من هذه الخيارات يعمل بشكل جيد؛ يمكنك إضافة المزيد لاحقاً.','Next'=>'التالي','Step 2 of 2: connect %s'=>'الخطوة ٢ من ٢: توصيل %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'أدخل عنوان خدمتك المتوافقة مع OpenAI، منتهيًا بـ /v1. لا يلزم وجود مفتاح إلا إذا طلبت الخدمة ذلك.','Open %s and sign in (or create a free account).'=>'افتح %s وسجل الدخول (أو أنشئ حساباً مجانياً).','the %s API keys page'=>'صفحة مفاتيح API الخاصة بـ %s','Create a new key and copy it.'=>'أنشئ مفتاحاً جديداً وانسخه.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'الصقه أدناه واضغط على "حفظ واختبار". نرسل طلباً صغيراً واحداً للتحقق من عمله.','Most providers need a little credit on the account before a key works: %s.'=>'تحتاج معظم الشركات المزودة إلى رصيد بسيط في الحساب قبل أن يعمل المفتاح: %s.','add credit'=>'إضافة رصيد','← Choose a different provider'=>'← اختر مزوداً مختلفاً','Address'=>'العنوان','Saved key ends in …%s — paste a new one to replace it'=>'تنتهي المفتاح المحفوظ بـ …%s — الصق مفتاحاً جديداً لاستبداله','Key (optional)'=>'مفتاح (اختياري)','API key'=>'مفتاح واجهة برمجة التطبيقات','Save and test'=>'حفظ واختبار','Providers'=>'مزودو الخدمة','Provider'=>'المزود','Status'=>'الحالة','Key'=>'مفتاح','Get a key'=>'احصل على مفتاح','Test'=>'اختبار','Remove'=>'إزالة','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'تم الحفظ بواسطة إصدار أحدث من الإضافة: قم بتحديث هذه الإضافة، أو أدخل المفتاح مرة أخرى.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'لم يعد من الممكن فتح المفتاح المحفوظ (تغيرت مفاتيح الأمان الخاصة بالموقع). أدخله مرة أخرى.','Not connected'=>'غير متصل','Connected — last test passed %s'=>'متصل — نجح الاختبار الأخير %s','Last test failed: %s'=>'فشل الاختبار الأخير: %s','Connected — not tested yet'=>'متصل — لم يتم الاختبار بعد','Which model to use'=>'ما النموذج المراد استخدامه','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ تشير إلى توصيتنا لتلك المهمة. تتضمن القائمة كل نموذج يمكن لمفتاحك استخدامه، وتُقرأ مباشرة من المزود.','— Recommended for the provider —'=>'— مُوصى به للمزوّد —','Save models'=>'حفظ النماذج','Refresh the model lists from the providers'=>'تحديث قوائم النماذج من المزودين','best quality'=>'أفضل جودة','lowest cost'=>'أقل تكلفة','fastest'=>'الأسرع','Add a model yourself'=>'أضف نموذجاً بنفسك','A model came out today? Paste its exact name to use it straight away.'=>'صدر نموذج جديد اليوم؟ الصق اسمه الدقيق لاستخدامه على الفور.','Model name'=>'اسم النموذج','Add model'=>'إضافة نموذج','Recommended models list'=>'قائمة النماذج الموصى بها','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'تعذر التحقق من قائمة النماذج الموصى بها، لذا لا يتم عرض أي توصيات. أعد تثبيت المكون الإضافي، أو قم بتفعيل التحديثات اليومية أدناه.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'تم نشر القائمة المستخدمة في %s. يجلب كل تحديث للإضافة قائمة جديدة.','Also check Zinn Digital® once a day for an updated list.'=>'تحقق أيضًا من Zinn Digital® مرة واحدة في اليوم للحصول على قائمة محدثة.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'لا يُرسل سوى طلب تنزيل عادي: لا مفتاح، ولا عنوان موقع، ولا شيء عن محتواك. القائمة موقعة، وتلك التي تُخفق في التحقق من التوقيع يتم تجاهلها.','Last checked %1$s: %2$s.'=>'آخر فحص في %1$s: %2$s.','Save, and check now if turned on'=>'احفظ، ثم تحقق الآن مما إذا كان مشغلاً','a newer list was installed'=>'تم تثبيت قائمة أحدث','already up to date'=>'محدث بالفعل','the download failed the signature check and was ignored'=>'فشل التنزيل في اختبار التوقيع وتم تجاهله','Zinn Digital® could not be reached; the current list stays in use'=>'تعذر الاتصال بـ Zinn Digital®؛ ستبقى القائمة الحالية قيد الاستخدام','turned off'=>'متوقف','Open'=>'فتح','Check their status page'=>'تحقق من صفحة حالتهم','Open your billing page'=>'افتح صفحة الفواتير الخاصة بك','Open your API keys page'=>'افتح صفحة مفاتيح واجهة برمجة التطبيقات الخاصة بك','Open the AI settings'=>'فتح إعدادات الذكاء الاصطناعي','Sorry, you are not allowed to do that.'=>'عذراً، لا يُسمح لك بتنفيذ هذا الإجراء.','Unknown provider.'=>'مزوّد غير معروف.','Enter the address of your service, for example http://localhost:11434/v1.'=>'أدخل عنوان خدمتك، على سبيل المثال http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'لا يبدو هذا مفتاح واجهة برمجة تطبيقات. انسخه مرة أخرى بدون مسافات.','Paste your API key first.'=>'الصق مفتاح واجهة برمجة التطبيقات الخاص بك أولاً.','Key removed.'=>'تم إزالة المفتاح.','Models saved.'=>'تم حفظ النماذج.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'أدخل اسم النموذج بدقة، على النحو الوارد في وثائق المزود على سبيل المثال.','Added %s. Choose it under "Which model to use".'=>'تمت إضافة %s. اختره تحت "أي نموذج يجب استخدامه".','Model removed.'=>'تمت إزالة النموذج.','Daily updates are off. The list that came with the plugin is used.'=>'التحديثات اليومية متوقفة. تُستخدم القائمة التي جاءت مع المكون الإضافي.','Checked: %s.'=>'تم التحقق: %s.','Model lists refreshed.'=>'تم تحديث قوائم النماذج.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'تم حفظ مفتاح الذكاء الاصطناعي الخاص بك بواسطة إصدار أحدث من إحدى المكونات الإضافية الخاصة بك. قم بتحديث هذا المكون الإضافي، أو أدخل المفتاح مرة أخرى في إعدادات الذكاء الاصطناعي.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'لم يعد من الممكن فتح مفتاح الذكاء الاصطناعي المحفوظ الخاص بك (تغيرت مفاتيح الأمان الخاصة بالموقع). أدخله مرة أخرى في إعدادات الذكاء الاصطناعي.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'لم يتم إعداد الذكاء الاصطناعي بعد. أضف مفتاحاً لمزود الذكاء الاصطناعي في إعدادات الذكاء الاصطناعي.','No model is chosen for this task. Pick one in the AI settings.'=>'لم يتم اختيار أي نموذج لهذه المهام. قم باختيار واحد في إعدادات الذكاء الاصطناعي.','That AI provider is not supported by this version of the plugin.'=>'مزود الذكاء الاصطناعي هذا غير مدعوم من هذا الإصدار من الملحق.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'تعذر على هذا الموقع الوصول إلى خدمة الذكاء الاصطناعي الخاصة بك. تحقق من أنها قيد التشغيل وأن عنوانها قابل للوصول من خادم الويب الخاص بك (لا يمكن الوصول إلى خدمة على جهاز الكمبيوتر الخاص بك من موقع مستضاف).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'تعذر على هذا الموقع الوصول إلى %s. تحقق من صفحة الحالة الخاصة به؛ فإذا كان يعمل، فقد يقوم مُستضيفك بحظر الاتصالات الصادرة، أو أن العنوان غير صحيح.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'يقول %s إن حسابك ليس به رصيد أو حصة متبقية. أضف رصيداً أو ارفع حدك في حسابك معهم، ثم حاول مرة أخرى.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'لم يقبل %s مفتاحك. قد يكون مكتوباً بشكل خاطئ أو ملغياً أو منتهي الصلاحية. انشئ مفتاحاً جديداً وألصقه هنا.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'رفض %s هذا الطلب الخاص بمفتاحك. قد لا يمتلك المفتاح إمكانية الوصول إلى هذا النموذج أو الميزة، أو أن حسابك بحاجة إلى التحقق.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'النموذج "%1$s" غير متاح من %2$s لمفتاحك. اختر نموذجاً آخر في إعدادات الذكاء الاصطناعي.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'لا تتضمن باقة %2$s الخاصة بك النموذج "%1$s". اختر نموذجاً آخر في إعدادات الذكاء الاصطناعي، أو قم ترقية باقتك معهم.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'يقوم %s بتقييد سرعة إرسال مفتاحك للطلبات. انتظر دقيقة وحاول مرة أخرى، أو ارفع حد المعدل الخاص بك معهم.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'يواجه %s مشكلات في الوقت الحالي (انقطاع أو ضغط زائد من جانبهم). إعداداتك سليمة تماماً. أعد المحاولة بعد قليل.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'فشل طلب الذكاء الاصطناعي لسبب لم نتمكن من تحديده. حاول مرة أخرى؛ وإذا استمر حدوث ذلك، فاتصل بالدعم مع تقديم التفاصيل أدناه.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'أجاب موفر الذكاء الاصطناعي بصيغة تعذر على هذا البرنامج المساعد قراءتها. حاول مرة أخرى؛ وإذا استمر حدوث ذلك، فاختر نموذجاً آخر أو اتصل بالدعم.','Custom (OpenAI-compatible)'=>'مخصص (متوافق مع OpenAI)','Save a key for this provider first.'=>'احفظ مفتاحاً لهذا المزود أولاً.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'مفتاحك يعمل، لكن المزود لا يدرج أي نموذج نصي له. أضف نموذجاً بنفسك أدناه.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'متصل. أجاب %1$s باستخدام %2$s. ميزات الذكاء الاصطناعي الخاصة بك جاهزة للاستخدام.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'دور مستخدمك غير مسموح له باستخدام الذكاء الاصطناعي على هذا الموقع. اتصل بالمسؤول.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'لقد بلغ هذا الموقع الحد الأقصى الشهري للإنفاق على الذكاء الاصطناعي. يمكن للمسؤول رفع هذا الحد من إعدادات الذكاء الاصطناعي.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'لقد بلغ هذا الموقع حده الشهري من طلبات الذكاء الاصطناعي. يمكن للمسؤول زيادة هذا الحد في إعدادات الذكاء الاصطناعي.','Usage and cost'=>'الاستخدام والتكلفة','The log, limits and role permissions apply to AI used through: %s.'=>'تسري السجلات والحدود وأدوار الصلاحيات على الذكاء الاصطناعي المستخدم عبر: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'التكاليف تقريبية، ومحسوبة من الأسعار المنشورة؛ النموذج الذي ليس له سعر معروف يُحسب كصفر.','This month: %1$s requests, about %2$s.'=>'هذا الشهر: %1$s طلب، حوالي %2$s.','When'=>'متى','Who'=>'من','Used for'=>'مستخدم لـ','Model'=>'النموذج','Tokens in / out'=>'رمزوز الدخول / الخروج','About'=>'حول','Result'=>'النتيجة','No AI requests have been made yet.'=>'لم يتم إرسال أي طلبات ذكاء اصطناعي بعد.','Done'=>'تم الانتهاء','Limits and permissions'=>'الحدود والأذونات','Monthly spending limit (US dollars)'=>'الحد الأقصى للإنفاق الشهرى (بالدولار الأمريكي US)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'اتركه فارغاً بلا حد. يتوقف الذكاء الاصطناعي عن العمل لبقية الشهر بمجرد وصول التكلفة التقريبية إليه.','Monthly request limit'=>'حد الطلبات الشهري','Leave empty for no limit.'=>'اتركه فارغاً بلا حد.','Who may use AI'=>'من يمكنه استخدام الذكاء الاصطناعي','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'لم يتم اختيار شيء للسماح لكل من يستطيع استخدام ميزات الملحق باستخدام الذكاء الاصطناعي. يمكن للمسؤولين استخدامه دائماً.','Save limits and permissions'=>'حفظ الحدود والصلاحيات','Limits and permissions saved.'=>'تم حفظ الحدود والأذونات.','That language is not one of this site\'s languages.'=>'هذه اللغة ليست إحدى لغات هذا الموقع.','A translation must be the same kind of content as the original.'=>'يجب أن تكون الترجمة من نفس نوع محتوى النص الأصلي.','Choose one of the site\'s other languages.'=>'اختر إحدى لغات الموقع الأخرى.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'نصوص شاشة المسؤول مفقودة من هذه النسخة من الملحق البرمجي. أعد تثبيته من حزمة مُصْدَرَة.','This screen needs JavaScript.'=>'هذه الشاشة تتطلب تشغيل جافاسكريبت.','Choose a language'=>'اختر لغة','Upgrade'=>'ترقية','Pricing'=>'الأسعار','Start Trial'=>'بدء التجربة','Account'=>'الحساب','Contact Us'=>'اتصل بنا','Affiliation'=>'الانتساب','the kind of softwarePlugin'=>'إضافة برمجية','greetingHey %s,'=>'أهلاً %s،','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'اشترك لتلقي إشعارات البريد الإلكتروني للتحديثات الأمنية والميزات، والمحتوى التعليمي، والعروض من حين لآخر، ولتشارك بعض معلومات بيئة WordPress الأساسية. سيكساعدنا هذا في جعل %s أكثر توافقاً مع موقعك وأفضل في أداء ما تحتاجه منه.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'اشترك لتلقي إشعارات البريد الإلكتروني للتحديثات الأمنية والميزات، والمحتوى التعليمي، والعروض من حين لآخر، ولتشارك بعض معلومات بيئة WordPress الأساسية.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'إذا تخطيت هذا، فلا باس! سيظل %1$s يعمل بشكل جيد.','Allow & Continue'=>'سماح ومتابعة','verbSkip'=>'تخطي','Skipping, please wait'=>'جاري التخطي، يرجى الانتظار','Continue'=>'متابعة','Please wait'=>'يرجى الانتظار','as activating pluginActivating'=>'جار التفعيل','This will allow %s to'=>'سيسمح هذا لـ %s بـ','Privacy Policy'=>'سياسة الخصوصية','Terms of Service'=>'شروط الخدمة','License Agreement'=>'اتفاقية الترخيص','Have a license key?'=>'هل لديك مفتاح ترخيص؟','Activate License'=>'تفعيل الترخيص','View Basic Profile Info'=>'عرض معلومات الملف الشخصي الأساسية','Your WordPress user\'s: first & last name, and email address'=>'بيانات مستخدم WordPress الخاصة بك: الاسم الأول والاسم الأخير، وعنوان البريد الإلكتروني','View Basic Website Info'=>'عرض معلومات الموقع الأساسية','Homepage URL & title, WP & PHP versions, and site language'=>'رابط الصفحة الرئيسية وعنوانها، إصدارات ووردبريس (WP) وبي إتش بي (PHP)، ولغة الموقع','View Basic %s Info'=>'عرض معلومات %s الأساسية','Current %s & SDK versions, and if active or uninstalled'=>'الإصدارات الحالية لـ %s ومجموعة أدوات التطوير (SDK)، وما إذا كانت نشطة أو غير مُثبّتة','Newsletter'=>'النشرة الإخبارية','Updates, announcements, marketing, no spam'=>'تحديثات، إعلانات، تسويق، بدون رسائل مزعجة','View Diagnostic Info'=>'عرض معلومات التشخيص','WordPress & PHP versions, site language & title'=>'إصدارات WordPress و PHP، لغة الموقع وعنوانه','View Plugins & Themes List'=>'عرض قائمة الملحقات والسمات','Names, slugs, versions, and if active or not'=>'الأسماء، والروابط المختصرة، والإصدارات، وما إذا كانت مفعلة أم لا','optional'=>'اختياري','Never miss an important update'=>'لا تفوت أي تحديث مهم','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'لقد قدمنا هذا الخيار الاختياري لكي لا تفوتك أبداً أي تحديث مهم ولتساعدنا في جعل %s أكثر توافقاً مع موقعك وأفضل في أداء ما تحتاجه منه.','Thank you for updating to %1$s v%2$s!'=>'شكراً لتحديثك إلى %1$s الإصدار %2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'يجب أن يتكون البادئة من 1 إلى 8 أحرف صغيرة أو أرقام، وأن تبدأ بحرف، ويجب ألا تحمل اسم الملحق.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" ليس رمز لغة. استخدم لغة WordPress المحلية مثل fr_FR أو de_DE.','List at least one language.'=>'أدرج لغة واحدة على الأقل.','You are not allowed to translate this item.'=>'غير مسموح لك بتنزيل أو ترجمة هذا العنصر.','This item already has a version in that language.'=>'هذا العنصر لديه بالفعل نسخة بهذه اللغات.','That translation engine is not available on this site.'=>'محرك الترجمة هذا غير متوفر على هذا الموقع.','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'المحركات المختلفة لكل لغة، والاحتياط التلقائي، وحدود الإنفاق هي ميزات خاصة بـ Tranzly Pro.','Each language must be one of the site\'s languages, with an available engine.'=>'يجب أن تكون كل لغة إحدى لغات الموقع، مع توفر محرك لها.','The fallback list may only name available engines.'=>'قائمة البدائل الاحتياطية يمكن أن تذكر المحركات المتاحة فقط.','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'الحد الأقصى الشهري هو مبلغ بالدولار الأمريكي (US)، يساوي الصفر أو أكثر، لمحرك متاح.','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'الترجمات المفضلة والنبرة حسب اللغة هي من ميزات Tranzly Pro. قائمة عدم الترجمة مجانية.','Glossary entries must be grouped by one of the site\'s languages.'=>'يجب تجميع مداخل المسرد حسب إحدى لغات الموقع.','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'يتم ضبط النبرة لكل لغة موقع: الرسمية الافتراضية، بدرجات متفاوتة، بالإضافة إلى تعليمات اختيارية.','The value for %s is not one of the allowed choices.'=>'القيمة المقترحة لـ %s ليست ضمن الخيارات المسموح بها.','The background queue is not available on this site.'=>'قائمة الانتظار في الخلفية غير متوفرة على هذا الموقع.','A translation job runs as the person who starts it, so a user must be signed in.'=>'يتم تشغيل مهمة الترجمة بصفتها الشخص الذي بدأها، لذا يجب أن يكون المستخدم مسجلاً الدخول.','There is nothing you are allowed to translate in that selection.'=>'لا يوجد شيء مسموح لك بترجمته في هذا الاختيار.','That item is not part of a translation job.'=>'هذا العنصر ليس جزءاً من مهمة ترجمة.','You are not allowed to change that translation.'=>'لا يُسمح لك بتغيير تلك الترجمة.','This item\'s group already has a %1$s version (#%2$d).'=>'يحتوي بالفعل مجموعة هذا العنصر على نسخة %1$s (رقم %2$d).','An item cannot be its own translation.'=>'لا يمكن للعنصر أن يكون ترجمة لنفسه.','That item is already a translation of something else. Unlink it first.'=>'هذا العنصر هو بالفعل ترجمة لشيء آخر. قم بإلغاء ربطه أولاً.','The translation link could not be saved.'=>'تعذر حفظ رابط الترجمة.','That text cannot be translated here.'=>'لا يمكن ترجمة هذا النص هنا.','That media text cannot be translated here.'=>'لا يمكن ترجمة نص الوسائط هذا هنا.','A translation can be published or kept as a draft.'=>'يمكن نشر الترجمة أو الاحتفاظ بها كمسودة.','You are not allowed to publish this kind of content.'=>'غير مسموح لك بنشر هذا النوع من المحتوى.','This item is already written in that language.'=>'هذا العنصر مكتوب بالفعل بهذه اللغة.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'تم تعديل هذه الترجمة بواسطة شخص (أو استيرادها)، لذا فهي محمية. قم إلغاء قفلها لتراجمتها مرة أخرى.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'لم يتم إعداد أي محرك ترجمة حتى الآن. أضف مفتاحاً لأحدها في Tranzly ← المحركات.','That translation engine is not set up yet: add its key first.'=>'محرك الترجمة هذا غير معد بعد: أضف مفتاحه أولاً.','The same text is being translated by another job right now; this item will use that answer.'=>'جاري ترجمة نفس النص بواسطة مهمة أخرى الآن؛ سيستخدم هذا العنصر تلك الإجابة.','No translation engine could take this item.'=>'لم يتمكن أي محرك ترجمة من معالجة هذا العنصر.','The engine did not return a translation for every part of this item. Nothing was changed.'=>'لم يُرجع المحرك ترجمة لكل جزء من هذا العنصر. لم يتم تغيير شيء.','AI model'=>'نموذج الذكاء الاصطناعي','AI model (%1$s %2$s)'=>'نموذج الذكاء الاصطناعي (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'يعاني %s من مشاكل في الوقت الحالي. حاول مرة أخرى لاحقاً، أو استخدم محركاً آخر.','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'تعذر على موقعك الوصول إلى %s. تحقق من قدرته على إجراء اتصالات صادرة، ثم حاول مرة أخرى.','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'لم يقبل %s مفتاح واجهة برمجة التطبيقات الخاص بك. تحقق من المفتاح في Tranzly → Engines.','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'لقد استنفد حسابك %s الحصة أو الرصيد المخصص له. قم بشحنه معهم، أو استخدم محركاً آخر.','%s asked us to slow down. It will be tried again automatically.'=>'طلب %s منا الإبطاء. سيتم المحاولة مرة أخرى تلقائياً.','This text is too long for %s in one go. Split the content, or use another engine.'=>'هذا النص طويل جداً بالنسبة لـ %s دفعة واحدة. قم بتقسيم المحتوى، أو استخدم محركاً آخر.','%s refused to translate this content. Try another engine, or translate it by hand.'=>'رفض %s ترجمة هذا المحتوى. جرب محركاً آخر، أو ترجمه يدوياً.','%s does not translate this language. Choose another engine for it.'=>'لا يترجم %s هذه اللغة. اختر محركاً آخر لها.','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'تم بلوغ الحد الأقصى للإنفاق لهذا الشهر لـ %s، لذا لم يُرسل أي شيء إضافي إليه. قم برفع الحد الأقصى في Tranzly → Engines، أو انتظر حتى الشهر القادم.','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'فشلت الترجمة باستخدام %s لسبب لم تستطع Tranzly تحديده. التفاصيل أدناه.','An engine id must be lowercase letters, digits and hyphens.'=>'يجب أن تتكون معرفات المحرك من أحرف صغيرة وأرقام وشرطات.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'تم إنشاؤه بواسطة Neil Lock، المدير التنفيذي لشركة Zinn Digital® Ltd','Version %s'=>'الإصدار %s','Tranzly website'=>'موقع Tranzly','Zinn Digital® website'=>'موقع Zinn Digital® الإلكتروني','Settings saved.'=>'تم حفظ الإعدادات.','See the Pro plans and pricing'=>'اطلع على خطط الأسعار والأسعار المتقدمة Pro','Languages'=>'اللغات','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'اللغة الأولى هي التي كتب بها المحتوى الخاص بك. يقوم الزوار بالتبديل باستخدام كتلة مبدل اللغات.','(default)'=>'(الافتراضي)','Locale code'=>'رمز الإعدادات المحلية','For example fr_FR'=>'على سبيل المثال fr_FR','Name (optional)'=>'الاسم (اختياري)','For example Français'=>'على سبيل المثال Français','Add language'=>'إضافة لغة','Front-end output'=>'مخرج الواجهة الأمامية','Class name prefix'=>'بادئة اسم الفئة','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'كل اسم فئة يطبعها المكون الإضافي على صفحاتك يبدأ بهذا البادئة، بحيث لا تكشف الصفحات عن المكون الإضافي الذي أنشأها. من 1 إلى 8 أحرف صغيرة أو أرقام، تبدأ بحرف.','Beta updates'=>'تحديثات تجريبية','This site receives beta versions as updates.'=>'يتلقى هذا الموقع نسخاً تجريبية كتحديثات.','This site receives stable versions only.'=>'هذا الموقع يتلقى الإصدارات المستقرة فقط.','Change this on the Account page'=>'قم بتغيير هذا في صفحة الحساب','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'تُقدم الإصدارات التجريبية لتثبيتات Pro المرخصة المتصلة بحساباتهم. بمجرد الاتصال، يمكنك الانضمام من صفحة الحساب.','Save settings'=>'حفظ الإعدادات','First engine that is set up'=>'أول محرك تم إعداده','Key saved. It is stored encrypted and never shown again.'=>'تم حفظ المفتاح. يتم تخزينه مشفراً ولا يُعرض مرة أخرى.','Engine settings saved.'=>'تم حفظ إعدادات المحرك.','Glossary saved.'=>'تم حفظ المسرد.','Your keys'=>'مفاتيحك','Tranzly calls the translation services with your own account. Keys are stored encrypted in your database and are only ever sent to the service they belong to. AI model keys are set in the AI settings.'=>'تستدعي Tranzly خدمات الترجمة باستخدام حسابك الخاص. تُخزن المفاتيح مشفرة في قاعدة بياناتك ولا تُرسل مطلقاً إلا إلى الخدمة التي تنتمي إليها. يتم تعيين مفاتيح نموذج الذكاء الاصطناعي في إعدادات الذكاء الاصطناعي.','%s API key'=>'%s مفتاح واجهة برمجة التطبيقات','Saved: %s. Enter a new key to replace it, or save an empty field to remove it.'=>'تم الحفظ: %s. أدخل مفتاحاً جديداً استبداله، أو احفظ حقلًا فارغاً لإزالته.','No key saved.'=>'لم يتم حفظ أي مفتاح.','Azure region (leave empty for a global resource)'=>'منطقة Azure (اتركها فارغة للموارد العامة)','Save key'=>'حفظ المفتاح','Check my DeepL usage'=>'تحقق من استخدام DeepL الخاص بي','%1$s of %2$s characters used this billing period.'=>'تم استخدام %1$s من أصل %2$s حرفاً في فترة الفوترة هذه.','Which engine translates'=>'أي محرك يقوم بالترجمة','No engine is set up yet. Save a key above (or set up an AI model) to start translating.'=>'لم يتم إعداد أي محرك بعد. احفظ مفتاحاً في الأعلى (أو قم بإعداد نموذج ذكاء اصطناعي) لبدء الترجمة.','Default engine'=>'محرك افتراضي','A different engine per language, automatic fallback and monthly spending caps are Tranzly Pro features.'=>'محرك مختلف لكل لغة، والرجوع التلقائي، وحدود الإنفاق الشهرية هي ميزات Tranzly Pro.','Engine for %s'=>'محرك لـ %s','The default engine'=>'المحرك الافتراضي','If an engine fails or reaches a limit, try these next, in this order'=>'إذا تعطل محرك أو بلغ حدا أقصى، جرب هذه الخطوات التالية بهذا الترتيب','Monthly spending caps'=>'الحدود الشهرية للإنفاق','When an engine reaches its cap, nothing more is sent to it until next month and the failed-translation report says why. Leave empty for no cap.'=>'عندما تصل محرك الترجمة إلى الحد الأقصى، لا يتم إرسال أي شيء إضافي إليه حتى الشهر القادم، ويوضح تقرير الترجمات الفاشلة السبب. اترك الحقل فارغاً لعدم تعيين حد أقصى.','%1$s (spent this month: $%2$s)'=>'%1$s (المبلغ المنفق هذا الشهر: $%2$s)','Save caps'=>'حفظ الأحرف الكبيرة','Glossary and words never translated'=>'مسرد الكلمات التي لا تُترجم أبداً','Never translate these words (one per line)'=>'لا تترجم هذه الكلمات أبدًا (كلمة واحدة في كل سطر)','Brand and product names stay exactly as they are, with every engine.'=>'تبقى أسماء العلامات التجارية والمنتجات كما هي تماماً، مع كل محرك.','Preferred translations and tone per language are Tranzly Pro features.'=>'الترجمات المفضلة والنبرة لكل لغة هي من ميزات Tranzly Pro.','Preferred translations (one per line: term = translation)'=>'الترجمات المفضلة (واحدة في كل سطر: المصطلح = الترجمة)','Formality'=>'الرسمية','Default'=>'افتراضي','Formal'=>'رسمي','Informal'=>'غير رسمي','Style instructions (audience, brand voice)'=>'تعليمات النمط (الجمهور، صوت العلامة التجارية)','Save glossary'=>'حفظ المسرد','Job started with %d translations to do. It runs in the background: you can close this page.'=>'بدأت الوظيفة مع إجراء %d ترجمة. تعمل في الخلفية: يمكنك إغلاق هذه الصفحة.','Queued again.'=>'أُعِيد وضعها في قائمة الانتظار.','Running'=>'قيد التشغيل','Finished'=>'مكتمل','Cancelled'=>'ملغي','Translate in the background'=>'الترجمة في الخلفية','Set up a translation engine in the Engines tab first.'=>'قم بإعداد محرك ترجمة في علامة تبويب المحركات أولاً.','Translate every'=>'ترجم الكل','Into'=>'إلى','With'=>'مع','Each language’s own engine'=>'محرك كل لغة الخاص بها','Publish the translations (otherwise they are saved as drafts)'=>'انشر الترجمات (وإلا سيتم حفظها كمسودات)','Estimate the cost'=>'قدّر التكلفة','%1$d posts, %2$s characters. The price for this engine is not known in advance.'=>'%1$d منشور، %2$s حرفاً. سعر هذا المحرك غير معروف مسبقاً.','%1$d posts, %2$s characters: about $%3$s on your own account.'=>'%1$d منشور، %2$s حرفاً: حوالي $%3$s على حسابك الخاص.','Start translating'=>'ابدأ الترجمة','Jobs'=>'الوظائف','No translation jobs yet.'=>'لا توجد مهام ترجمة بعد.','Job %1$d — %2$s'=>'المهمة %1$d — %2$s','%1$d of %2$d translated, %3$d failed, %4$d skipped (protected or already in that language)'=>'تمت ترجمة %1$d من %2$d، وفشل %3$d، وتم تخطي %4$d (محمي أو مترجم بالفعل إلى تلك اللغة)','Stop this job'=>'إيقاف هذه المهمة','See what failed and why'=>'اعرف ما الذي فشل ولماذا','Content'=>'المحتوى','Language'=>'اللغة','What went wrong'=>'ما الذي حدث من خطأ','Fix it'=>'إصلاح المشكلة','Details'=>'التفاصيل','Retry with'=>'أعد المحاولة مع','The same engine'=>'نفس المحرك','Retry'=>'إعادة المحاولة','Translate by hand'=>'الترجمة يدوياً','Languages and settings'=>'اللغات والإعدادات','Engines'=>'محركات','Translation jobs'=>'مهام الترجمة','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'أضف لغة ثانية ضمن Tranzly في قائمة الإدارة، وسيظهر محول اللغات هنا.','Switcher'=>'محول','Accessible label'=>'تسمية يمكن الوصول إليها','block titleLanguage switcher'=>'مبدل اللغة','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'روابط تؤدي إلى هذه الصفحة بكل لغة من لغات الموقع. لا يتم عرض أي شيء حتى يتم إدراج لغتين أو أكثر.','block keywordlanguage'=>'اللغة','block keywordswitcher'=>'محول','block keywordtranslation'=>'ترجمة']];